?><!doctype html><html lang="sw"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>VideoFunds Admin</title><style>*{box-sizing:border-box}body{margin:0;background:#f3f6fb;color:#17243a;font:15px Arial}.top{background:#12233b;color:white;padding:20px 4%;display:flex;justify-content:space-between;align-items:center}.wrap{max-width:1200px;margin:28px auto;padding:0 16px}.stats{display:flex;gap:12px;flex-wrap:wrap}.stat,.panel{background:white;border-radius:14px;padding:18px;box-shadow:0 4px 20px #182b4510}.stat{min-width:150px}.stat b{font-size:24px;display:block}.panel{margin-top:18px}.bar{display:flex;gap:10px;flex-wrap:wrap}.bar input,.bar select,.bar textarea{padding:11px;border:1px solid #d3dce8;border-radius:8px}.bar input{flex:1;min-width:200px}button,.btn{border:0;border-radius:8px;padding:10px 13px;background:#1767c5;color:#fff;text-decoration:none;cursor:pointer}.danger{background:#c63b4d}.muted{background:#53657c}.green{background:#178653}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:760px}th,td{text-align:left;padding:12px;border-bottom:1px solid #e8edf4}th{background:#f7f9fc}.pill{padding:5px 8px;border-radius:20px;background:#e5f7ed;color:#08743c}.pill.off{background:#ffe8eb;color:#a52336}.err{background:#ffe7e9;padding:12px;border-radius:8px;color:#8e2030}.forms{display:grid;grid-template-columns:1fr 1fr;gap:15px}.forms form{background:#f8fafc;padding:15px;border-radius:10px}.forms textarea{width:100%;min-height:80px}@media(max-width:650px){.forms{grid-template-columns:1fr}}</style><header class="top"><div><b>VideoFunds / Admin Panel</b><div style="font-size:12px;color:#b8c9df"><?=h(VF_ADMIN_EMAIL)?></div></div><a class="btn muted" href="/admin/logout.php">Logout</a></header><main class="wrap"><div class="stats"><div class="stat"><span>Users wanaoonekana</span><b><?=count($users)?></b></div><div class="stat"><span>Accounts zilizoban</span><b><?=count(array_filter($users,fn($u)=>